import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";

const root = process.cwd();
const schemaPath = path.join(root, "drizzle", "schema.pg.ts");
const outDir = path.join(root, "docs", "db-parity", "migrations", "lab-disabled", "manual");
const source = fs.readFileSync(schemaPath, "utf8");

const sqlQuote = (value) => `"${value.replaceAll('"', '""')}"`;
const literalQuote = (value) => `'${value.replaceAll("'", "''")}'`;

function matchingBrace(input, start) {
  let depth = 0;
  let quote = null;
  let escaped = false;

  for (let index = start; index < input.length; index += 1) {
    const char = input[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === "'" || char === '"' || char === "`") {
      quote = char;
      continue;
    }
    if (char === "{") depth += 1;
    if (char === "}") {
      depth -= 1;
      if (depth === 0) return index;
    }
  }
  throw new Error(`Unclosed object beginning at character ${start}`);
}

function parseEnums(input) {
  const enums = new Map();
  const regex = /export const (\w+) = pgEnum\('([^']+)',\s*(\[[\s\S]*?\])\);/g;
  for (const match of input.matchAll(regex)) {
    const [, symbol, typeName, rawValues] = match;
    const values = [...rawValues.matchAll(/["']((?:\\.|[^"'])*)["']/g)].map((value) => value[1]);
    if (values.length === 0) throw new Error(`Enum ${symbol} has no parsed values`);
    enums.set(symbol, { typeName, values });
  }
  return enums;
}

function sqlDefault(expression) {
  const raw = expression.trim();
  if (raw === "true") return "TRUE";
  if (raw === "false") return "FALSE";
  if (/^-?\d+(\.\d+)?$/.test(raw)) return raw;
  const stringMatch = raw.match(/^["'](.*)["']$/s);
  if (stringMatch) return literalQuote(stringMatch[1]);
  return null;
}

function columnSql(fieldName, expression, enums) {
  let type = null;
  const enumSymbol = expression.match(/^(\w+Enum)\(/)?.[1];
  if (enumSymbol && enums.has(enumSymbol)) type = sqlQuote(enums.get(enumSymbol).typeName);
  else if (/^integer\(/.test(expression)) type = "integer";
  else if (/^smallint\(/.test(expression)) type = "smallint";
  else if (/^bigint\(/.test(expression)) type = "bigint";
  else if (/^boolean\(/.test(expression)) type = "boolean";
  else if (/^decimal\(/.test(expression)) {
    const precision = expression.match(/precision:\s*(\d+)/)?.[1];
    const scale = expression.match(/scale:\s*(\d+)/)?.[1];
    type = precision && scale ? `numeric(${precision}, ${scale})` : "numeric";
  } else if (/^varchar\(/.test(expression)) {
    const length = expression.match(/length:\s*(\d+)/)?.[1];
    type = length ? `varchar(${length})` : "varchar";
  } else if (/^text\(/.test(expression)) type = "text";
  else if (/^timestamp\(/.test(expression)) type = "timestamp with time zone";

  if (!type) throw new Error(`Unsupported column expression ${fieldName}: ${expression}`);

  const pieces = [sqlQuote(fieldName), type];
  if (expression.includes("generatedByDefaultAsIdentity")) pieces.push("GENERATED BY DEFAULT AS IDENTITY");
  if (expression.includes(".defaultNow()")) pieces.push("DEFAULT CURRENT_TIMESTAMP");
  else {
    const defaultExpression = expression.match(/\.default\(([^)]*)\)/)?.[1];
    if (defaultExpression) {
      const parsed = sqlDefault(defaultExpression);
      if (parsed) pieces.push(`DEFAULT ${parsed}`);
    }
  }
  if (expression.includes(".notNull()")) pieces.push("NOT NULL");
  if (expression.includes(".primaryKey()")) pieces.push("PRIMARY KEY");
  if (expression.includes(".unique()")) pieces.push("UNIQUE");
  return pieces.join(" ");
}

function parseColumns(body, enums) {
  const columns = [];
  for (const line of body.split("\n")) {
    const match = line.match(/^\s*(\w+):\s*(.+?),\s*(?:\/\/.*)?$/);
    if (match) columns.push({ name: match[1], sql: columnSql(match[1], match[2], enums) });
  }
  return columns;
}

function parseIndexes(callbackBody) {
  const indexes = [];
  const regex = /(uniqueIndex|index)\("([^"]+)"\)\.on\(([\s\S]*?)\)\s*(?:,|$)/g;
  for (const match of callbackBody.matchAll(regex)) {
    const [, kind, name, rawColumns] = match;
    const columns = [...rawColumns.matchAll(/table\.(\w+)/g)].map((column) => column[1]);
    if (columns.length > 0) indexes.push({ name, unique: kind === "uniqueIndex", columns });
  }
  return indexes;
}

function parseTables(input, enums) {
  const tables = [];
  const regex = /export const (\w+) = pgTable\("([^"]+)",\s*\{/g;
  for (const match of input.matchAll(regex)) {
    const [full, symbol, physicalName] = match;
    const objectStart = match.index + full.length - 1;
    const objectEnd = matchingBrace(input, objectStart);
    const columns = parseColumns(input.slice(objectStart + 1, objectEnd), enums);
    if (columns.length === 0) throw new Error(`Table ${symbol} has no parsed columns`);

    const nextTableStart = input.indexOf("export const ", objectEnd + 1);
    const tableTail = input.slice(objectEnd, nextTableStart >= 0 ? nextTableStart : input.length);
    const callbackStart = tableTail.indexOf("(table) => ({");
    let indexes = [];
    if (callbackStart >= 0) {
      const callbackObjectStart = objectEnd + callbackStart + "(table) => (".length;
      const callbackObjectEnd = matchingBrace(input, callbackObjectStart);
      indexes = parseIndexes(input.slice(callbackObjectStart + 1, callbackObjectEnd));
    } else {
      const returnObjectStart = tableTail.indexOf("return {");
      if (returnObjectStart >= 0) {
        const callbackObjectStart = objectEnd + returnObjectStart + "return ".length;
        const callbackObjectEnd = matchingBrace(input, callbackObjectStart);
        indexes = parseIndexes(input.slice(callbackObjectStart + 1, callbackObjectEnd));
      }
    }
    tables.push({ symbol, physicalName, columns, indexes });
  }
  return tables;
}

function banner(title) {
  return [
    "-- ============================================================================",
    `-- ${title}`,
    "-- S2-A REVIEW ARTIFACT ONLY — DO NOT APPLY, RENAME, MOVE OR EXECUTE.",
    "-- No database connection was used to create this file.",
    "-- This file remains disabled until a later explicit Lab-only execution gate.",
    "-- ============================================================================",
    "",
  ].join("\n");
}

function postgresIndexName(sourceName, tableName) {
  const candidate = `${sourceName}__${tableName}`;
  if (Buffer.byteLength(candidate, "utf8") <= 63) return candidate;
  const digest = createHash("sha256").update(candidate).digest("hex").slice(0, 8);
  return `${candidate.slice(0, 54)}_${digest}`;
}

const enums = parseEnums(source);
const tables = parseTables(source, enums);
const expectedTableCount = Number(process.env.S2A_EXPECTED_TABLES ?? "95");
if (tables.length !== expectedTableCount) throw new Error(`Expected ${expectedTableCount} tables, parsed ${tables.length}`);

fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

const enumSql = banner("M02 — enum and domain type proposal") + [...enums.values()]
  .map(({ typeName, values }) => `CREATE TYPE ${sqlQuote(typeName)} AS ENUM (${values.map(literalQuote).join(", ")});`)
  .join("\n") + "\n";

const tableSql = banner("M03 — base table and identity proposal") + tables
  .map((table) => `CREATE TABLE ${sqlQuote(table.physicalName)} (\n  ${table.columns.map((column) => column.sql).join(",\n  ")}\n);`)
  .join("\n\n") + "\n";

const indexEntries = tables.flatMap((table) => table.indexes.map((index) => ({ ...index, tableName: table.physicalName })));
const indexNameCounts = new Map();
for (const entry of indexEntries) indexNameCounts.set(entry.name, (indexNameCounts.get(entry.name) ?? 0) + 1);
const indexNameResolutions = indexEntries
  .filter((entry) => indexNameCounts.get(entry.name) > 1)
  .map((entry) => ({ sourceName: entry.name, resolvedName: postgresIndexName(entry.name, entry.tableName), tableName: entry.tableName }));
const indexSql = banner("M04 — index and unique proposal") + indexEntries
  .map((entry) => {
    const resolvedName = indexNameCounts.get(entry.name) > 1 ? postgresIndexName(entry.name, entry.tableName) : entry.name;
    return `CREATE ${entry.unique ? "UNIQUE " : ""}INDEX ${sqlQuote(resolvedName)} ON ${sqlQuote(entry.tableName)} (${entry.columns.map(sqlQuote).join(", ")});`;
  })
  .join("\n") + "\n";

fs.writeFileSync(path.join(outDir, "M02-enum-and-domain-types.sql.disabled"), enumSql);
fs.writeFileSync(path.join(outDir, "M03-base-tables-and-identity.sql.disabled"), tableSql);
fs.writeFileSync(path.join(outDir, "M04-indexes-and-unique.sql.disabled"), indexSql);
fs.writeFileSync(path.join(outDir, "bundle-summary.json"), JSON.stringify({
  status: "disabled_manual_review_artifact",
  source: "drizzle/schema.pg.ts",
  tableCount: tables.length,
  enumCount: enums.size,
  indexCount: indexEntries.length,
  indexNameCollisionEntries: indexNameResolutions.length,
  omittedStages: ["M05-validated-constraints", "M06-runtime-grants"],
  connectionUsed: false,
}, null, 2) + "\n");
fs.writeFileSync(path.join(outDir, "index-name-resolution.json"), JSON.stringify({
  rule: "PostgreSQL index names share the schema namespace. Any duplicate source name is made table-scoped with __<tableName>.",
  postgresIdentifierLimit: 63,
  resolutions: indexNameResolutions,
}, null, 2) + "\n");

console.log(JSON.stringify({ tables: tables.length, enums: enums.size, indexes: indexEntries.length, indexNameCollisionEntries: indexNameResolutions.length }));
